"name":"Kurucaşile"},"931":{"province":"74","name":"Merkez"},"932":{"province":"74","name":"Ulus"},"933":{"province":"75","name":"Çıldır"},"934":{"province":"75","name":"Damal"},"935":{"province":"75","name":"Göle"},"936":{"province":"75","name":"Hanak"},"937":{"province":"75","name":"Merkez"},"938":{"province":"75","name":"Posof"},"939":{"province":"76","name":"Aralık"},"940":{"province":"76","name":"Karakoyunlu"},"941":{"province":"76","name":"Merkez"},"942":{"province":"76","name":"Tuzluca"},"943":{"province":"77","name":"Altınova"},"944":{"province":"77","name":"Armutlu"},"945":{"province":"77","name":"Çiftlikköy"},"946":{"province":"77","name":"Çınarcık"},"947":{"province":"77","name":"Merkez"},"948":{"province":"77","name":"Termal"},"949":{"province":"78","name":"Eflani"},"950":{"province":"78","name":"Eskipazar"},"951":{"province":"78","name":"Merkez"},"952":{"province":"78","name":"Ovacık"},"953":{"province":"78","name":"Safranbolu"},"954":{"province":"78","name":"Yenice"},"955":{"province":"79","name":"Elbeyli"},"956":{"province":"79","name":"Merkez"},"957":{"province":"79","name":"Musabeyli"},"958":{"province":"79","name":"Polateli"},"959":{"province":"80","name":"Bahçe"},"960":{"province":"80","name":"Düziçi"},"961":{"province":"80","name":"Hasanbeyli"},"962":{"province":"80","name":"Kadirli"},"963":{"province":"80","name":"Merkez"},"964":{"province":"80","name":"Sumbas"},"965":{"province":"80","name":"Toprakkale"},"966":{"province":"81","name":"Akçakoca"},"967":{"province":"81","name":"Çilimli"},"968":{"province":"81","name":"Cumayeri"},"969":{"province":"81","name":"Gölyaka"},"970":{"province":"81","name":"Gümüşova"},"971":{"province":"81","name":"Kaynaşlı"},"972":{"province":"81","name":"Merkez"},"973":{"province":"81","name":"Yığılca"}}$districts$::jsonb;
 fullname text:=left(trim(regexp_replace(coalesce(p_name,''),'[[:space:]]+',' ','g')),120);
 province text:=left(trim(regexp_replace(coalesce(p_province,''),'[[:space:]]+',' ','g')),100);
 district text:=left(trim(regexp_replace(coalesce(p_district,''),'[[:space:]]+',' ','g')),100);
 district_data jsonb;
begin
 if fullname='' or province='' or district='' then return null;end if;
 if coalesce(nullif(p_country,''),'TR')='TR' then
  if province ~ '^[0-9]+$' then
   province:=provinces->>province;
   if province is null then return null;end if;
  end if;
  if district ~ '^[0-9]+$' then
   district_data:=districts->district;
   if district_data is null or (provinces->>(district_data->>'province')) is distinct from province then return null;end if;
   district:=district_data->>'name';
  end if;
 end if;
 return jsonb_build_object('full_name',fullname,'province',province,'district',district);
end $profile$;
revoke all on function agroverix_private.notice_profile(text,text,text,text) from public,anon,authenticated;

create or replace function public.agroverix_notification_claim(p_worker_key text,p_limit integer default 5) returns jsonb
language plpgsql security definer set search_path='' as $claim$
declare result jsonb;
begin
 if not exists(select 1 from agroverix_private.notification_settings where singleton and enabled and extensions.digest(worker_key,'sha256')=extensions.digest(coalesce(p_worker_key,''),'sha256')) then
  raise exception 'Unauthorized' using errcode='42501';
 end if;
 update agroverix_private.admin_notification_outbox set state='failed',last_error='DELIVERY_RETRY_LIMIT'
 where state='processing' and leased_at<now()-interval '10 minutes' and attempts>=6;
 with candidates as(
  select n.id,d.details from agroverix_private.admin_notification_outbox n
  left join public.farmer_profiles p on p.user_id=n.user_id
  cross join lateral(select case when n.event_kind='signup'
   then coalesce(n.signup_profile,agroverix_private.notice_profile(p.full_name,p.province,p.district,p.country))
   else null end as details) d
  where n.attempts<6 and ((n.state='pending' and n.available_at<=now()) or (n.state='processing' and n.leased_at<now()-interval '10 minutes'))
   and (n.event_kind<>'signup' or d.details is not null)
  order by n.occurred_at,n.id for update of n skip locked limit greatest(1,least(coalesce(p_limit,5),10))
 ),claimed as(
  update agroverix_private.admin_notification_outbox n set state='processing',attempts=attempts+1,leased_at=now(),lease_id=gen_random_uuid(),
   signup_profile=case when n.event_kind='signup' then c.details else null end
  from candidates c where n.id=c.id returning n.id,n.event_kind,n.occurred_at,n.lease_id,n.signup_profile
 )
 select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'kind',c.event_kind,'occurred_at',c.occurred_at,'lease_id',c.lease_id,'recipient',s.recipient)
  ||case when c.event_kind='signup' then jsonb_build_object('profile',c.signup_profile) else '{}'::jsonb end),'[]'::jsonb)
 into result from claimed c cross join agroverix_private.notification_settings s where s.singleton;
 return result;
end $claim$;
revoke all on function public.agroverix_notification_claim(text,integer) from public,anon,authenticated;
grant execute on function public.agroverix_notification_claim(text,integer) to service_role;
notify pgrst,'reload schema';
